import { CheckoutService, ICheckoutService } from "@/core/services/checkout-service";
import { usePayment } from "@/core/hooks";
import { useEffect, useState } from "react";
import { EventAggregator } from "@/core/helpers";
import { CheckoutError, CheckoutLoading } from "@/core/components/primitives/shop-service-status/shop-service-status";
import styles from "./klarna-checkout.module.less";

// https://docs.klarna.com/kco/additional-resources/client-side-events/
type KustomClientApi = {
  suspend(): void;
  resume(): void;
  on(handlers: { redirect_initiated?: () => void }): void;
};
const kustomClientApi = (callback: (api: KustomClientApi) => void) => (window as any)._klarnaCheckout?.(callback);

type Props = {
  cartId: string;
  checkoutService?: ICheckoutService;
};

export const KlarnaCheckout = ({ cartId, checkoutService = CheckoutService }: Props) => {
  const [kustomContainer, setKustomContainer] = useState<HTMLDivElement | null>(null);

  const { data: payment, isLoading, error, isFetching } = usePayment(cartId, checkoutService);

  /**
   * The htmlSnippet has script tags in it
   * We need to re-evaluate the script tags to make them actually run
   * This means loading the content, adding the script tags to the DOM, removing the old script tags and adding the new ones
   * Source: https://docs.klarna.com/kco/integrate-kco-in-your-ecommerce/render-checkout-snippet/
   */
  useEffect(() => {
    if (!kustomContainer) {
      return undefined;
    }

    const scriptTags = kustomContainer.getElementsByTagName("script");
    for (const thisScriptTag of scriptTags) {
      const parentNode = thisScriptTag.parentNode;
      const newScriptTag = document.createElement("script");
      newScriptTag.type = "text/javascript";
      newScriptTag.text = thisScriptTag.text;
      parentNode?.removeChild(thisScriptTag);
      parentNode?.appendChild(newScriptTag);
    }

    kustomClientApi((api) => {
      api.on({
        redirect_initiated: () => {
          EventAggregator.publish("klarnaRedirectInitiated", undefined);
        },
      });
    });
  }, [kustomContainer]);

  // When the payment response is updated, for example when the user adds/removes a gift card, we need to suspend and resume the Klarna client
  useEffect(() => {
    if (!kustomContainer) return;

    kustomClientApi(async (api) => {
      api.suspend();
      await new Promise((resolve) => setTimeout(resolve, 500));
      api.resume();
    });
    // we can ignore the `kustomContainer` dependency here, since we only want to run this effect when the container is mounted
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [payment]);

  // When the payment is loading, we need to suspend the Klarna client
  useEffect(() => {
    if (!kustomContainer) return;

    kustomClientApi((api) => {
      if (isFetching) {
        api.suspend();
      } else {
        api.resume();
      }
    });
    // we can ignore the `kustomContainer` dependency here, since we only want to run this effect when the container is mounted
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isFetching]);

  if (!!payment?.paymentProvider && payment.paymentProvider !== "Klarna") {
    throw new Error(`KlarnaCheckout can only be used with Klarna payments, got ${payment.paymentProvider}`);
  }
  // Somehow TypeScript doesn't infer this type when run from the terminal, but it works in my IDE. Casting for consistency.
  const klarnaPayment = payment as (typeof payment & { paymentProvider: "Klarna" }) | undefined;

  return (
    <div className={styles.wrapper}>
      {isLoading && <CheckoutLoading />}
      {error && <CheckoutError />}
      {klarnaPayment && !error && !isLoading && (
        <div
          className={styles.klarnaContainer}
          ref={setKustomContainer}
          dangerouslySetInnerHTML={{ __html: klarnaPayment.htmlSnippet }}
        />
      )}
    </div>
  );
};
