import { useState } from "react";
import { Script } from "gatsby-script";

// Refer to the following documentation for more details https://developer.nexigroup.com/nexi-checkout/en-EU/api/checkout-js-sdk/
export type DibsCheckoutInstance = {
  // There are more events to subscribe to. Check documentation linked above.
  on(eventName: "payment-completed", callback: (response: PaymentCompletedResponse) => void): void;
  /** NOTE: if used, the checkout flow will not proceed the payment when the customer clicks pay unless we send the 'payment-order-finalized' event */
  on(eventName: "pay-initialized", callback: (response: PaymentInitializedResponse) => void | Promise<void>): void;

  /**
   * @deprecated DANGER! DO NOT USE!
   *
   * According to the documentation, this should only removes all event listeners and not destroy/remove the entire
   * instance. But in practice, using this can cause race conditions where it removes all styling, disables auto-resize,
   * and makes the instance unusable.
   *
   * Instead of using this, just re-add an event listener if needed, as that removes the previous one.
   */
  cleanup(): void;

  /** Continues (or aborts) the payment process, after the `pay-initialized` event has completed */
  send(eventName: "payment-order-finalized", doContinue: boolean): void;

  /** Freezes checkout to allow updates to cart/payment */
  freezeCheckout(): void;
  /** Thaws checkout to continue after updates to cart/payment have been applied */
  thawCheckout(): void;
};
export type PaymentCompletedResponse = {
  paymentId: string;
};
export type PaymentInitializedResponse = {
  paymentId: string;
};
export type DibsConstructor = {
  Checkout: {
    new (options: CheckoutOptions): DibsCheckoutInstance;
  };
};
export type DibsTheme = Partial<Record<DibsStylingOptions, string>>;
export type CheckoutOptions = {
  checkoutKey: string;
  paymentId: string;
  containerId: string;
  language: NetsAllowedLanguages;
  theme: DibsTheme;
};
// This list can be found here https://developer.nexigroup.com/nexi-checkout/en-EU/api/#localization
export type NetsAllowedLanguages =
  | "en-GB"
  | "da-DK"
  | "nl-NL"
  | "ee-EE"
  | "fi-FI"
  | "fr-FR"
  | "de-DE"
  | "it-IT"
  | "lv-LV"
  | "lt-LT"
  | "nb-NO"
  | "pl-PL"
  | "es-ES"
  | "sk-SK"
  | "sv-SE";
export type DibsStylingOptions =
  | "textColor"
  | "primaryColor"
  | "linkColor"
  | "backgroundColor"
  | "fontFamily"
  | "placeholderColor"
  | "outlineColor"
  | "primaryOutlineColor"
  | "panelColor"
  | "panelTextColor"
  | "panelLinkColor"
  | "buttonRadius"
  | "buttonbackgroundColor"
  | "buttonTextColor"
  | "buttonFontWeight"
  | "buttonFontStyle"
  | "buttonTextTransform"
  | "useLightIcons";

export function useNetsCheckoutScript(scriptUrl: string) {
  const [isLoaded, setIsLoaded] = useState(false);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const Dibs = typeof window === "undefined" || !isLoaded ? undefined : ((window as any).Dibs as DibsConstructor);

  const scriptElement = <Script src={scriptUrl} onLoad={() => setIsLoaded(true)} />;

  return { Dibs, scriptElement };
}
