import { CheckoutService, ICheckoutService } from "@/core/services/checkout-service";
import {
  DibsCheckoutInstance,
  DibsTheme,
  NetsAllowedLanguages,
  useCart,
  useNetsCheckoutScript,
  usePayment,
  useValidateNetsPayment,
} from "@/core/hooks";
import { useCallback, useEffect, useId, useState } from "react";
import styles from "./nets-checkout.module.less";
import { CheckoutError, CheckoutLoading } from "@/core/components/primitives/shop-service-status/shop-service-status";
import { Language } from "@/core/labels/i18n";
import { navigate } from "gatsby-link";
import { useStaticConfigContext } from "@/core/contexts";
import { EventAggregator } from "@/core/helpers";
import { NetsPaymentResponse } from "@parksandresorts/webapiproxy-types";
import { paymentToPurchaseGTMEvent, trackEcommerceEvent } from "@/core/helpers/gtm-helper";
import { ShopUrlSlugOverrides } from "@/core/types/shop-service-types";

const GATSBY_NETS_CHECKOUT_URL = process.env.GATSBY_NETS_CHECKOUT_URL as string;

const defaultLanguage = "sv-SE" satisfies NetsAllowedLanguages;
const languageMap = {
  en: "en-GB",
  sv: "sv-SE",
  nn: "nb-NO",
} satisfies Record<Language, NetsAllowedLanguages>;

const isNetsPaymentOrUndefined = (
  payment: ReturnType<typeof usePayment>["data"],
): payment is Extract<ReturnType<typeof usePayment>["data"], NetsPaymentResponse | undefined> =>
  !payment?.paymentProvider || payment.paymentProvider === ("Nets" satisfies NetsPaymentResponse["paymentProvider"]);

type Props = {
  cartId: string;
  locale: Language;
  theme: DibsTheme | undefined;
  shopUrlSlugOverrides: ShopUrlSlugOverrides | undefined;
  checkoutService?: ICheckoutService;
};
export const NetsCheckout = ({
  cartId,
  locale,
  theme,
  shopUrlSlugOverrides,
  checkoutService = CheckoutService,
}: Props) => {
  const { eCommerce } = useStaticConfigContext();

  const { data: cart } = useCart(cartId, checkoutService);
  const { data: payment } = usePayment(cartId, checkoutService);

  const confirmationSlug = shopUrlSlugOverrides?.confirmationUrl ?? eCommerce.shopServiceConfirmationSlug;
  const postCheckoutUrl = `${confirmationSlug}?cartId=${cartId}`;
  const onPaymentCompleted = useCallback(() => {
    navigate(postCheckoutUrl);

    if (!cart || !payment) return;
    trackEcommerceEvent(paymentToPurchaseGTMEvent(cart, payment));
  }, [postCheckoutUrl, cart, payment]);

  return (
    <NetsCheckoutIframe
      cartId={cartId}
      locale={locale}
      theme={theme}
      checkoutService={checkoutService}
      onPaymentCompleted={onPaymentCompleted}
    />
  );
};

type IframeProps = Omit<Props, "shopUrlSlugOverrides"> & {
  onPaymentCompleted?: () => void;
};
export const NetsCheckoutIframe = ({
  cartId,
  locale,
  theme,
  onPaymentCompleted,
  checkoutService = CheckoutService,
}: IframeProps) => {
  if (!GATSBY_NETS_CHECKOUT_URL)
    throw new Error("Nets checkout URL expected to be configured using GATSBY_NETS_CHECKOUT_URL in .env");

  const [netsContainer, setNetsContainer] = useState<HTMLDivElement | null>(null);

  const { data: payment, isLoading, error: paymentError, isFetching } = usePayment(cartId, checkoutService);
  if (!isNetsPaymentOrUndefined(payment)) {
    throw new Error(`NetsCheckout can only be used with Nets payments, got ${payment?.paymentProvider}`);
  }

  const { Dibs, scriptElement } = useNetsCheckoutScript(GATSBY_NETS_CHECKOUT_URL);
  const [activeCheckout, setActiveCheckout] = useState<DibsCheckoutInstance>();
  const checkoutContainerId = useId();

  useEffect(() => {
    if (!netsContainer || !theme || !payment?.paymentId || !Dibs) {
      return;
    }

    const language = languageMap[locale] ?? defaultLanguage;
    if (!languageMap[locale]) {
      console.warn(`No configured lanugage for locale ${locale}, defaulting to ${defaultLanguage}`);
    }

    netsContainer.id = checkoutContainerId;
    const checkout = new Dibs.Checkout({
      checkoutKey: payment.checkoutKey,
      paymentId: payment.paymentId,
      containerId: checkoutContainerId,
      language,
      theme,
    });
    setActiveCheckout(checkout);
  }, [Dibs, payment?.paymentId, payment?.checkoutKey, netsContainer, theme, checkoutContainerId, locale]);

  const { mutateAsync: validatePayment, error: validationError } = useValidateNetsPayment(cartId, checkoutService);

  const error = paymentError || validationError;

  // Set up Nets event listeners
  useEffect(() => {
    if (activeCheckout == null) return undefined;

    activeCheckout.on("payment-completed", () => {
      onPaymentCompleted?.();
    });

    // Since the `cleanup` method is a bit unreliable (see documentation), we override the listener with a noop.
    return () => activeCheckout.on("payment-completed", () => undefined);
  }, [activeCheckout, onPaymentCompleted]);
  useEffect(() => {
    if (activeCheckout == null) return undefined;

    activeCheckout.on("pay-initialized", async () => {
      // Let's do some additional validation before proceeding with the payment
      try {
        await validatePayment();
        // If validation passed, continue the payment process
        activeCheckout.send("payment-order-finalized", true);
      } catch (error) {
        activeCheckout.send("payment-order-finalized", false);
        EventAggregator.publish("trackException", {
          exception: error,
          customMessage: `Nets payment validation failed for cartId ${cartId}`,
        });
      }
    });

    // Since the `cleanup` method is a bit unreliable (see documentation), we override with a listener that instantly
    // finalizes the payment as "cleanup". This is comparable to the default behaviour when there is no listener.
    return () => {
      activeCheckout.on("pay-initialized", () => {
        activeCheckout.send("payment-order-finalized", true);
      });
    };
  }, [activeCheckout, validatePayment, cartId]);

  // When the payment response is updated, for example when the user adds/removes a gift card, we need to suspend and resume the Nets client
  useEffect(() => {
    if (!activeCheckout) return;

    Promise.resolve().then(async () => {
      activeCheckout.freezeCheckout();
      await new Promise((resolve) => setTimeout(resolve, 500));
      activeCheckout.thawCheckout();
    });
    // we can ignore the `activeCheckout` dependency here, since we only want to run this effect after the checkout is active
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [payment]);

  // When the payment is loading, we need to suspend the Nets client
  useEffect(() => {
    if (!activeCheckout) return;

    if (isFetching) {
      activeCheckout.freezeCheckout();
    } else {
      activeCheckout.thawCheckout();
    }
    // we can ignore the `activeCheckout` dependency here, since we only want to run this effect after the checkout is active
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isFetching]);

  return (
    <div className={styles.wrapper}>
      {scriptElement}
      {isLoading && <CheckoutLoading />}
      {error && <CheckoutError />}
      {payment && !error && !isLoading && <div ref={setNetsContainer} />}
    </div>
  );
};
